:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  min-height: 100%;
  background: #0a0a0a;
  font-family: system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
}

.main {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  color: #e5e7eb;
}

.section {
  width: min(100%,440px);
  display: grid;
  gap: 16px;
}

.section h1 {
  margin: 0;
  font-size: 20px;
}

.counter-control {
  display: grid;
  gap: 12px;
  padding: 20px;
  border: 1px solid #334155;
  border-radius: 16px;
  background: #0b1020;
  outline: none;
}

.counter-control:focus-visible {
  box-shadow: 0 0 0 3px #facc15;
}

.value {
  font-size: 48px;
  line-height: 1;
  font-weight: 800;
  text-align: center;
}

.step-label {
  font-size: 13px;
  font-weight: 700;
}

.step-select {
  width: 100%;
  padding: 9px 10px;
  border: 1px solid #475569;
  border-radius: 9px;
  background: #111827;
  color: #f8fafc;
}

.shortcuts {
  margin: 0;
  color: #cbd5e1;
  font-size: 12px;
  line-height: 1.45;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.actions button {
  padding: 9px 13px;
  border: 0;
  border-radius: 10px;
  background: #a3e635;
  color: #111827;
  font-weight: 750;
  cursor: pointer;
}

.actions button[disabled] {
  opacity: .5;
  cursor: not-allowed;
}

.actions .ghost {
  background: transparent;
  color: #e5e7eb;
